import{_ as a,H as i,f as o,i as n}from"./chunks/framework.CBmkDW73.js";const _=JSON.parse('{"title":"품질 표준 프로토콜 (Quality Standard)","description":"","frontmatter":{},"headers":[],"relativePath":"ko/skills/quality.md","filePath":"ko/skills/quality.md"}'),t={name:"ko/skills/quality.md"};function l(d,e,r,c,s,h){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="품질-표준-프로토콜-quality-standard" tabindex="-1">품질 표준 프로토콜 (Quality Standard) <a class="header-anchor" href="#품질-표준-프로토콜-quality-standard" aria-label="Permalink to &quot;품질 표준 프로토콜 (Quality Standard)&quot;">​</a></h1><p>품질 표준 (<code>skills/references/quality.md</code>)은 <code>tdd</code>, <code>review</code>, <code>ship</code>, <code>archive</code>, <code>onboard</code> 전반에서 강제 적용되는 품질 기준을 정의합니다.</p><h2 id="_3차원-품질-검증" tabindex="-1">3차원 품질 검증 <a class="header-anchor" href="#_3차원-품질-검증" aria-label="Permalink to &quot;3차원 품질 검증&quot;">​</a></h2><p>모든 구현 및 리팩토링 사이클마다 다음 4가지 관점에서 엄격히 검증합니다:</p><h3 id="_1-기계적-검사-mechanical-checks" tabindex="-1">1. 기계적 검사 (Mechanical Checks) <a class="header-anchor" href="#_1-기계적-검사-mechanical-checks" aria-label="Permalink to &quot;1. 기계적 검사 (Mechanical Checks)&quot;">​</a></h3><ul><li>Lint 규칙이 경고 없이 통과.</li><li>코드 포맷팅이 프로젝트 설정 준수.</li><li><code>any</code>를 통한 우회나 타입 오류 억제 없이 타입 검사(Typecheck) 통과.</li></ul><h3 id="_2-관례-준수-convention-adherence" tabindex="-1">2. 관례 준수 (Convention Adherence) <a class="header-anchor" href="#_2-관례-준수-convention-adherence" aria-label="Permalink to &quot;2. 관례 준수 (Convention Adherence)&quot;">​</a></h3><ul><li>명세서(<code>convention:</code>)에 선언된 프로젝트 관례 및 스택 모범 사례 엄격 준수.</li><li>관용적 구조, 에러 처리 패턴 및 명명 규칙 평가.</li></ul><h3 id="_3-설계-및-경계-평가-design-boundaries" tabindex="-1">3. 설계 및 경계 평가 (Design &amp; Boundaries) <a class="header-anchor" href="#_3-설계-및-경계-평가-design-boundaries" aria-label="Permalink to &quot;3. 설계 및 경계 평가 (Design &amp; Boundaries)&quot;">​</a></h3><ul><li><strong>내향적 의존성 (Inward Dependencies)</strong>: 핵심 비즈니스 로직은 가변적인 I/O, UI, DB 어댑터에 의존하지 않음.</li><li><strong>부작용 격리 (Isolated Side-Effects)</strong>: 순수 계산 및 결정 로직을 I/O 및 상태 변이와 명확히 분리.</li><li><strong>고응집 및 단순성 (Cohesion &amp; Simplicity)</strong>: 단일 책임 원칙 준수; 비대해진 함수나 누출된 추상화 배제.</li></ul><h3 id="_4-문서-커버리지-documentation-coverage" tabindex="-1">4. 문서 커버리지 (Documentation Coverage) <a class="header-anchor" href="#_4-문서-커버리지-documentation-coverage" aria-label="Permalink to &quot;4. 문서 커버리지 (Documentation Coverage)&quot;">​</a></h3><ul><li>모든 공개 함수, API 엔드포인트, 내보낸 인터페이스, 환경 변수 및 오류 모드가 정확히 문서화됨.</li><li><code>README.md</code>의 명령어 및 예제가 실행 가능하고 최신 상태로 유지됨.</li><li>문서 업데이트가 누락된 코드 변경은 Code Review를 통과할 수 없음.</li></ul>',12)])])}const m=a(t,[["render",l]]);export{_ as __pageData,m as default};
